"""Intent tests for train.train (M1-T28): an interrupted run is kept as incomplete (RUN-02, AD-06)."""

import importlib.util
import json
from dataclasses import replace
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.core import SOLO, RunSettings, StepResult, Transition
from rllab.envs import Corridor
from rllab.train import train

TESTS = Path(__file__).resolve().parents[2]
CONTRACTS = TESTS / "contracts"
CORRIDOR = json.loads((TESTS / "fixtures" / "rllab" / "TC-11" / "input.json").read_text())

EVAL_EVERY = 5
STEPS = 1000
POINTS_BEFORE_INTERRUPT = 3
# Interrupt strictly after the third curve point (step 2 * EVAL_EVERY) and before the fourth.
INTERRUPT_AT = (POINTS_BEFORE_INTERRUPT - 1) * EVAL_EVERY + 3


def _codec() -> Any:
    spec = importlib.util.spec_from_file_location("contracts_codec", CONTRACTS / "codec.py")
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _settings() -> RunSettings:
    base = _codec().sample("core.RunSettings", "corridor_tabular", RunSettings)
    return replace(base, steps=STEPS, eval_every=EVAL_EVERY, eval_games=1)


def _make_env() -> Corridor:
    return Corridor(length=CORRIDOR["length"], max_steps=CORRIDOR["max_steps"])


class _RightAgent:
    """Always steps right; optionally raises KeyboardInterrupt on its n-th `learn` call."""

    def __init__(self, interrupt_on_learn: int | None) -> None:
        self.interrupt_on_learn = interrupt_on_learn
        self.learn_calls = 0

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        return np.ones((obs.shape[0],), dtype=np.int64)

    def learn(self, t: Transition) -> None:
        self.learn_calls += 1
        if self.interrupt_on_learn is not None and self.learn_calls == self.interrupt_on_learn:
            raise KeyboardInterrupt

    def save(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(b"right")

    def load(self, path: Path) -> None:
        return None


class _InterruptingCorridor:
    """A corridor whose n-th training `step` raises KeyboardInterrupt (counted across envs)."""

    calls = 0
    interrupt_at = INTERRUPT_AT

    def __init__(self) -> None:
        self._env = _make_env()
        self.teams = self._env.teams
        self.board = self._env.board

    def reset(self, seed: int) -> tuple[dict[str, np.ndarray], dict[str, float]]:
        return self._env.reset(seed)

    def step(self, actions: Any) -> StepResult:
        type(self).calls += 1
        if type(self).calls == type(self).interrupt_at:
            raise KeyboardInterrupt
        return self._env.step(actions)

    def frame(self) -> np.ndarray:
        return self._env.frame()


def _run_folder(root: Path) -> Path:
    folders = [p for p in root.iterdir() if p.is_dir()]
    assert len(folders) == 1, f"expected one run folder under {root}, found {folders}"
    return folders[0]


def _curve_steps(folder: Path) -> list[int]:
    steps = []
    for line in (folder / "curve.csv").read_text().splitlines():
        first = line.split(",")[0].strip()
        if first.lstrip("-").isdigit():
            steps.append(int(first))
    return steps


@pytest.mark.intent
def test_interrupt_after_three_points_is_reraised(tmp_path):
    agent = _RightAgent(interrupt_on_learn=INTERRUPT_AT)
    with pytest.raises(KeyboardInterrupt):
        train(_make_env, {SOLO: agent}, _settings(), root=tmp_path)
    assert agent.learn_calls == INTERRUPT_AT


@pytest.mark.intent
def test_interrupted_run_folder_has_status_incomplete(tmp_path):
    agent = _RightAgent(interrupt_on_learn=INTERRUPT_AT)
    with pytest.raises(KeyboardInterrupt):
        train(_make_env, {SOLO: agent}, _settings(), root=tmp_path)
    folder = _run_folder(tmp_path)
    assert (folder / "status").read_text().strip() == "incomplete"


@pytest.mark.intent
def test_interrupted_run_keeps_its_three_curve_points(tmp_path):
    agent = _RightAgent(interrupt_on_learn=INTERRUPT_AT)
    with pytest.raises(KeyboardInterrupt):
        train(_make_env, {SOLO: agent}, _settings(), root=tmp_path)
    folder = _run_folder(tmp_path)
    expected = [i * EVAL_EVERY for i in range(POINTS_BEFORE_INTERRUPT)]
    assert _curve_steps(folder) == expected


@pytest.mark.intent
def test_interrupted_run_keeps_its_settings(tmp_path):
    settings = _settings()
    agent = _RightAgent(interrupt_on_learn=INTERRUPT_AT)
    with pytest.raises(KeyboardInterrupt):
        train(_make_env, {SOLO: agent}, settings, root=tmp_path)
    folder = _run_folder(tmp_path)
    saved = json.loads((folder / "settings.json").read_text())
    assert saved["name"] == settings.name
    assert saved["seed"] == settings.seed
    assert saved["steps"] == settings.steps


@pytest.mark.intent
def test_interrupt_raised_by_the_environment_also_marks_incomplete(tmp_path, monkeypatch):
    monkeypatch.setattr(_InterruptingCorridor, "calls", 0)
    agent = _RightAgent(interrupt_on_learn=None)
    with pytest.raises(KeyboardInterrupt):
        train(_InterruptingCorridor, {SOLO: agent}, _settings(), root=tmp_path)
    folder = _run_folder(tmp_path)
    assert (folder / "status").read_text().strip() == "incomplete"
    assert _curve_steps(folder)[0] == 0

